function partnersPage(){const isCyr=state.script==='cyr';return `${pageHeading(isCyr?'Ҳамкорлар базаси':'Hamkorlar bazasi',isCyr?'Хизмат кўрсатувчилар, йўналишлар ва ҳамкорлик шартлари.':'Xizmat ko‘rsatuvchilar, yo‘nalishlar va hamkorlik shartlari.',`<button class="btn" data-action="partner-new">${icon('plus')} ${isCyr?'Ҳамкор қўшиш':'Hamkor qo‘shish'}</button>`)}<div class="filters"><input type="search" id="partner-search" placeholder="${isCyr?'Номи, телефон ёки ҳудуд…':'Nomi, telefon yoki hudud…'}" aria-label="Hamkor qidirish"><select id="partner-category" aria-label="Hamkor yo‘nalishi">${options(state.config.categories,'',isCyr?'Барча йўналишлар':'Barcha yo‘nalishlar')}</select></div><div class="panel" id="partner-results">${partnersTable(state.partners)}</div>`;}
function partnersTable(partners){const isCyr=state.script==='cyr';return partners.length?`<div class="table-scroll"><table><thead><tr><th>${isCyr?'Ҳамкор':'Hamkor'}</th><th>${isCyr?'Йўналиш / ҳудуд':'Yo‘nalish / hudud'}</th><th>${isCyr?'Алоқа':'Aloqa'}</th><th>${isCyr?'Хизмат шартлари':'Xizmat shartlari'}</th><th>${isCyr?'Шартнома':'Shartnoma'}</th></tr></thead><tbody>${partners.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.address)}</small></td><td>${esc(category(p.category))}<br><small>${esc(p.region)}</small></td><td><a href="tel:${esc(p.phone)}" class="tel-link">${esc(p.phone)}</a><br><small>${esc(p.hours)}</small></td><td>${money(p.price)}</td><td><span class="pill ${p.contractStatus==='active'?'green':'amber'}">${esc({active:'Amalda',pending:'Kutilmoqda',expired:'Muddati tugagan'}[p.contractStatus])}</span></td></tr>`).join('')}</tbody></table></div>`:empty(isCyr?'Ҳамкор топилмади':'Hamkor topilmadi',isCyr?'Янги ҳамкор қўшинг ёки филтрларни ўзгартиринг.':'Yangi hamkor qo‘shing yoki filtrlarni o‘zgartiring.');}
