function packageCards(){if(!state.packages.length)return `<div class="panel">${empty('Hozircha oila paketi yo‘q',staff()?'Mijoz uchun mos paket va foydalanish limitini belgilang.':'Oilangiz uchun mos paket haqida koordinatorga murojaat qiling.',!staff()?'<button class="btn" data-action="request" data-package="Komfort">Paket haqida so‘rash</button>':'')}</div>`;return `<div class="package-list">${state.packages.map(p=>`<article class="owned-package"><div class="detail-heading"><h3>${esc(p.tier)}</h3><span class="pill ${p.status==='active'?'green':'red'}">${({active:'Amalda',expired:'Muddati tugagan',exhausted:'Limit tugagan'})[p.status]}</span></div><p>${esc(p.clientName||state.user.name)}</p><div class="balance">${esc(p.remaining??Math.max(0,p.limit-p.used))} <small>/ ${esc(p.limit)} murojaat qoldi</small></div><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,Number(p.used)/Math.max(1,Number(p.limit))*100)}%"></div></div><p class="small-text muted" style="margin-top:12px">${esc(p.used)} ta foydalanilgan · ${date(p.expiresAt)} gacha</p><div class="member-tags">${p.members.map(n=>`<span>${esc(n)}</span>`).join('')}</div>${staff()?`<div class="form-actions"><button class="btn outline small" data-action="package-edit" data-id="${p.id}">O‘zgartirish</button><button class="btn small" data-action="package-use" data-id="${p.id}">Foydalanishni qayd etish</button></div>`:''}</article>`).join('')}</div>`;}
async function packageDialog(id=null,clientId=''){
 if(!state.clients.length)state.clients=(await api('/clients')).clients;if(id&&!state.packages.length)state.packages=(await api('/packages')).packages;
 const p=state.packages.find(p=>String(p.id)===String(id));const exp=new Date();exp.setFullYear(exp.getFullYear()+1);
 modalOpen(p?'Oila paketini yangilash':'Oila paketini belgilash','Bir mijoz uchun bitta amaldagi paket yuritiladi. Mavjud paket bo‘lsa yangilanadi.',`<form id="package-form">${formError}<div class="form-grid">${selectField('clientId','Mijoz',options(state.clients,p?.clientId||clientId,'Mijozni tanlang'),'required')}${selectField('tier','Paket',options(['Start','Komfort','Premium'],p?.tier||'Start'))}${field('expiresAt','Amal qilish muddati','date',(p?.expiresAt||exp.toISOString()).slice(0,10),'required')}${field('limit','Murojaatlar limiti','number',p?.limit??5,'required min="1" max="1000" step="1"')}${textareaField('members','Oila a’zolari · har biri yangi qatorda',p?.members.join('\n')||'','required maxlength="2000" placeholder="Ism va familiya"')}</div><div class="form-actions"><button type="submit" class="btn">Paketni saqlash</button></div></form>`);
}
