 return `${pageHeading(isCyr?'Хабарномалар навбати':'Xabarnomalar navbati',isCyr?'Мурожаатлар бўйича тайёрланган хабарлар.':'Murojaatlar bo‘yicha tayyorlangan xabarlar.')}<div class="notice">${isCyr?'Telegram бот ҳали уланмаган. Навбатдаги хабарлар юборилмаган. Телефон рақамининг ўзи Telegram хабар юбориш учун етарли эмас.':'Telegram bot hali ulanmagan. Navbatdagi xabarlar yuborilmagan. Telefon raqamining o‘zi Telegram xabar yuborish uchun yetarli emas.'}</div><div class="panel">${state.notifications.length?`<div class="table-scroll"><table><thead><tr><th>Murojaat</th><th>Telefon</th><th>Hodisa</th><th>Xabar</th><th>Holat</th><th>Sana</th></tr></thead><tbody>${state.notifications.map(n=>`<tr><td>${esc(n.caseNumber)}</td><td>${esc(n.recipientPhone||'—')}</td><td>${esc(notificationEvent(n.event))}</td><td>${esc(n.message||'—')}</td><td><span class="pill amber">${n.status==='sent'?'Yuborilgan deb qayd etilgan':'Navbatda'}</span></td><td>${date(n.createdAt,true)}</td></tr>`).join('')}</tbody></table></div>`:empty('Xabarnomalar yo‘q','Murojaatlar o‘zgarganda xabarlar shu yerda qayd etiladi.')}</div>`;
