function notificationEvent(event){return({'request.created':'Yangi murojaat','case.status_changed':'Murojaat holati o‘zgardi','service.assigned':'Xizmatga hamkor biriktirildi','service.status_changed':'Xizmat holati o‘zgardi',created:'Murojaat yaratildi',status_changed:'Holat o‘zgardi',request_created:'Yangi murojaat',case_created:'Yangi murojaat',case_updated:'Murojaat yangilandi',service_updated:'Xizmat yangilandi',completed:'Murojaat yakunlandi'}[event]||statusNames[event]||event);}
async function readAttachments(files){
 if(files.length>3)throw new Error('Ovozli xabar bilan birga jami 3 tagacha fayl qo‘shish mumkin.');
 const allowed=['image/jpeg','image/png','image/webp','application/pdf','audio/webm','audio/ogg','audio/mp4','audio/mpeg','audio/wav'];
 if(files.reduce((total,file)=>total+file.size,0)>2.8*1024*1024)throw new Error('Biriktirilgan fayllar jami 2.8 MB dan oshmasligi kerak.');
 for(const f of files){if(f.size>5*1024*1024)throw new Error(`${f.name}: fayl hajmi 5 MB dan oshmasligi kerak.`);if(!allowed.includes(f.type.split(';')[0]))throw new Error(`${f.name}: bu fayl turi qo‘llab-quvvatlanmaydi.`);}
 return Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type.split(';')[0],data:reader.result.split(',')[1]});reader.onerror=()=>reject(new Error('Faylni o‘qib bo‘lmadi.'));reader.readAsDataURL(file);})));
}
async function toggleRecording(button){
 if(recording?.state==='recording'){stopRecording();button.innerHTML=`${icon('mic')} Qayta yozish`;return;}
 if(!window.MediaRecorder||!navigator.mediaDevices?.getUserMedia){$('#record-status').textContent='Bu brauzerda yozish mavjud emas. Tayyor audio faylni yuklashingiz mumkin.';return;}
 const requestForm=$('#request-form');
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!requestForm?.isConnected||!modal.open){stream.getTracks().forEach(t=>t.stop());return;}const mime=['audio/webm','audio/ogg','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime){stream.getTracks().forEach(t=>t.stop());throw new Error('unsupported');}recording=new MediaRecorder(stream,{mimeType:mime});const chunks=[],recorder=recording;
 recording.addEventListener('dataavailable',e=>{if(e.data.size)chunks.push(e.data);});recording.addEventListener('stop',()=>{stream.getTracks().forEach(t=>t.stop());if(!requestForm.isConnected||!modal.open)return;const blob=new Blob(chunks,{type:mime});voiceFile=new File([blob],`ovozli-murojaat.${mime.split('/')[1]}`,{type:mime});if($('#record-status'))$('#record-status').textContent=`Ovozli xabar tayyor (${Math.max(1,Math.round(blob.size/1024))} KB). Yuborishda qo‘shiladi.`;if(button.isConnected)button.innerHTML=`${icon('mic')} Qayta yozish`;});recording.start();voiceFile=null;button.innerHTML=`${icon('mic')} Yozishni to‘xtatish`;$('#record-status').textContent='Yozilmoqda… 2 daqiqagacha.';setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},120000);
 }catch{if(requestForm?.isConnected&&$('#record-status'))$('#record-status').textContent='Mikrofonga kirib bo‘lmadi. Ruxsatni tekshiring yoki tayyor audio fayl yuklang.';}
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;e.preventDefault();
 try{
  if(action==='close')modalClose();
  else if(action==='request')requestDialog(button.dataset.category||(button.dataset.package?state.config.categories.find(c=>c.name==='Boshqa')?.id:''),button.dataset.package);
  else if(action==='request-unknown')requestDialog('','',true);
  else if(action==='toggle-script'){state.script=state.script==='cyr'?'lat':'cyr';localStorage.setItem('zar_script',state.script);await renderRoute();}
  else if(action==='case-tab'){state.filters.tab=button.dataset.tab;document.querySelectorAll('.case-tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.filters.tab));$('#case-results').innerHTML=staff()?caseTable(filteredCases()):caseCards(filteredCases());}
  else if(action==='user-new')userDialog();
  else if(action==='track')trackingDialog();
  else if(action==='track-prefill')trackingDialog(button.dataset.number,button.dataset.token);
  else if(action==='login')loginDialog();
  else if(action==='register')loginDialog(true);
  else if(action==='privacy')privacyDialog();
  else if(action==='cabinet')location.hash='cabinet/overview';
  else if(action==='logout'){await api('/auth/logout',{});state.user=null;state.cases=[];state.partners=[];state.clients=[];state.team=[];state.packages=[];state.stats=null;state.notifications=[];voiceFile=null;modalClose();modal.innerHTML='';state.filters={search:'',status:'',category:'',overdue:false,tab:'all'};app.dataset.page='';location.hash='home';await renderRoute();toast('Hisobdan chiqdingiz.');}
  else if(action==='copy'){try{await navigator.clipboard.writeText(button.dataset.text);toast('Nusxalandi. Maxfiy kalitni xavfsiz saqlang.');}catch{const input=document.createElement('textarea');input.value=button.dataset.text;modal.append(input);input.select();const ok=document.execCommand('copy');input.remove();toast(ok?'Nusxalandi.':'Nusxalab bo‘lmadi. Kalitni qo‘lda belgilab nusxalang.');}}
  else if(action==='record')await toggleRecording(button);
  else if(action==='case')await caseDialog(button.dataset.id);
  else if(action==='partner-new')partnerDialog();
  else if(action==='package-new')await packageDialog(null,button.dataset.client);
  else if(action==='package-edit')await packageDialog(button.dataset.id);
  else if(action==='package-use')packageUseDialog(button.dataset.id);
  else if(action==='refresh')await renderRoute();
  else if(action==='menu'){const open=$('.workspace').classList.toggle('menu-open');button.setAttribute('aria-expanded',String(open));}
 }catch(error){toast(error.message);}
});
document.addEventListener('input',e=>{if(['case-search','case-status','case-category','case-overdue'].includes(e.target.id))updateCaseFilter();if(['partner-search','partner-category'].includes(e.target.id)){const q=$('#partner-search').value.toLowerCase(),cat=$('#partner-category').value;$('#partner-results').innerHTML=partnersTable(state.partners.filter(p=>(!q||`${p.name} ${p.phone} ${p.region}`.toLowerCase().includes(q))&&(!cat||p.category===cat)));}});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const submit=form.querySelector('[type="submit"]'),original=submit?.innerHTML,errorBox=$('.form-error',form);if(errorBox)errorBox.innerHTML='';if(submit){submit.disabled=true;submit.textContent='Kutilmoqda…';}const data=Object.fromEntries(new FormData(form));
 try{
  if(form.id==='request-form'){if(recording?.state==='recording')throw new Error('Avval ovozli xabar yozishni to‘xtating.');const files=[...$('#attachments',form).files];if(voiceFile)files.push(voiceFile);data.attachments=await readAttachments(files);data.consent=data.consent==='on';const result=await api('/requests',data);successDialog(result);if(route())await renderRoute();}
  else if(form.id==='track-form'){const result=await api('/track',data);$('#tracking-result').innerHTML=`<div class="divider"></div>${caseReadOnly(result.case,data.token)}`;}
  else if(form.id==='login-form'||form.id==='register-form'){const register=form.id==='register-form';if(register)data.consent=data.consent==='on';state.user=(await api(register?'/auth/register':'/auth/login',data)).user;modalClose();app.dataset.page='';location.hash='cabinet/overview';await renderRoute();}
  else if(form.id==='feedback-form'){await api('/feedback',{...data,number:form.dataset.number,token:form.dataset.token,rating:Number(data.rating)});form.innerHTML='<div class="notice">Fikringiz uchun rahmat. Bahoyingiz saqlandi.</div>';toast('Baho saqlandi.');}
  else if(form.id==='case-update-form'){const body={status:data.status,priority:data.priority,coordinatorId:data.coordinatorId?Number(data.coordinatorId):null};if(data.dueAt)body.dueAt=new Date(data.dueAt).toISOString();if(data.note.trim())body.note=data.note.trim();const result=await api(`/cases/${form.dataset.id}`,body,'PATCH');renderCaseDialog(result.case);await renderRoute();toast('Murojaat yangilandi.');}
  else if(form.id==='service-add-form'){const body={title:data.title};if(data.partnerId)body.partnerId=Number(data.partnerId);if(data.price!=='')body.price=Number(data.price);const result=await api(`/cases/${form.dataset.id}/services`,body);renderCaseDialog(result.case);await renderRoute();toast('Xizmat qo‘shildi.');}
  else if(form.classList.contains('service-update-form')){const body={status:data.status};if(staff())body.partnerId=data.partnerId?Number(data.partnerId):null;const result=await api(`/services/${form.dataset.id}`,body,'PATCH');renderCaseDialog(result.case);await renderRoute();toast('Xizmat yangilandi.');}
  else if(form.id==='partner-form'){await api('/partners',{...data,price:Number(data.price)});modalClose();await renderRoute();toast('Hamkor ma’lumotnomaga qo‘shildi.');}
  else if(form.id==='package-form'){await api('/packages',{...data,clientId:Number(data.clientId),limit:Number(data.limit),expiresAt:new Date(data.expiresAt+'T23:59:59').toISOString(),members:data.members.split('\n').map(m=>m.trim()).filter(Boolean)});modalClose();await renderRoute();toast('Oila paketi saqlandi.');}
  else if(form.id==='package-use-form'){await api(`/packages/${form.dataset.id}/use`,{caseId:Number(data.caseId)});modalClose();await renderRoute();toast('Foydalanish hisobi yangilandi.');}
  else if(form.id==='user-create-form'){
    const body={name:data.name,phone:data.phone,login:data.login,role:data.role,password:data.password};
    if(data.role==='partner'&&data.partnerId)body.partnerId=Number(data.partnerId);
    await api('/users',body);
    modalClose();
    await renderRoute();
    toast(state.script==='cyr'?'Янги ходим ҳисоби яратилди!':'Yangi xodim hisobi yaratildi!');
  }
 }catch(error){if(errorBox?.isConnected){errorBox.innerHTML=`<div class="error-box">${esc(error.message)}</div>`;errorBox.scrollIntoView({block:'nearest'});}else toast(error.message);}finally{if(submit?.isConnected){submit.disabled=false;submit.innerHTML=original;}}
});
window.addEventListener('hashchange',()=>{if(state.config)renderRoute();});
async function init(){try{const [config,auth]=await Promise.all([api('/config'),api('/auth/me')]);state.config=config;state.user=auth.user;await renderRoute();if(location.hash==='#track')trackingDialog();}catch(error){app.innerHTML=`<main class="public-error" id="main">${brand()}<h1 style="margin-top:30px">Hozir ulanish imkoni bo‘lmadi.</h1><p class="muted">${esc(error.message)}</p><button class="btn" id="retry-init">Qayta urinib ko‘rish</button></main>`;$('#retry-init').addEventListener('click',init);}}
init();
